#!/usr/bin/env bash
# Dev-shell runtime bootstrap, sourced by the shellHook of this repo's
# flake (./bin/dev/pf-shell-enter.sh <PROJECT_NAME>) and of consumer flakes (shipped on PATH
# via the framework's nix package). Must be sourced (not executed): the
# .env exports must reach the interactive shell. Must run from the repo
# root ($PWD).
#
# Loads the repo-root .env (git-ignored, generated by `make dev-init`),
# best-effort refreshes private config (guarded by .private-source), and sets
# the tmux session alias. It does NOT start or resume a MariaDB daemon: the
# dev database instance lifecycle is owned by ema
# (`ema sandbox srv/<name>-<GUID>` builds + starts a per-instance sandbox;
# `ema start` / `ema stop` / `ema status` manage it).

if ! (return 0 2>/dev/null); then
    echo "pf-shell-enter.sh must be sourced, not executed" >&2
    exit 1
fi

if [ -z "${1:-}" ]; then
    echo "usage: source pf-shell-enter.sh <PROJECT_NAME>" >&2
    return 1 2>/dev/null || exit 1
fi
PROJECT_NAME="$1"

if [ -f .env ]; then
    set -a
    . ./.env
    set +a
else
    echo "No .env found - run 'make dev-init' inside this shell (required for runtime config)."
fi

# Best-effort private-config refresh at shell entry, so the checkout's etc/
# links stay current for the whole session. Guarded by .private-source (a
# no-op otherwise); GIT_TERMINAL_PROMPT=0 keeps git from prompting on a
# non-interactive fetch; never fatal (a trailing `:` keeps shell entry from
# failing), stdout quiet, warnings on stderr stay visible.
if [ -f .private-source ]; then
    if command -v fetch-private-data >/dev/null 2>&1; then
        GIT_TERMINAL_PROMPT=0 fetch-private-data >/dev/null || :
    elif [ -x ./bin/fetch-private-data ]; then
        GIT_TERMINAL_PROMPT=0 ./bin/fetch-private-data >/dev/null || :
    fi
fi

# Inherit nix shell env in tmux (doesn't include PS1)
# Requires 'set -g default-command ...' in .tmux.conf
alias tmux="command tmux -L \$PROJECT_NAME new-session -A -s \$PROJECT_NAME"
